use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = galley.menu.board();
    var i = 0;
    while i < dishes.len() {
        let dish = match dishes.get(index: i) {
            Some(d) => d,
            None => return Ok(unit),
        };
        if i > 0 {
            io.write(text: ";")?;
        }
        galley.kitchen.serve(io: io, dish: dish)?;
        i = i + 1;
    }
    return Ok(unit);
}

