pub fn entries() -> String {
    let signals = harbor.signal.signals();
    var parts: List<String> = [];
    var i = 0;
    while i < signals.len() {
        match signals.get(index: i) {
            Some(signal) => parts.push(item: render_signal(signal: signal)),
            None => unit,
        }
        i = i + 1;
    }
    parts.join(sep: ";")
}

fn render_signal(signal: harbor.signal.Signal) -> String {
    match signal {
        harbor.signal.Signal.Calm => "calm",
        harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
        harbor.signal.Signal.Fog(word) => "fog:".concat(other: word),
    }
}

