use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.Locker { label: "ax" };
    var bay = depot.locker.Locker { label: "bay" };
    var cod = depot.locker.Locker { label: "cod" };

    ax.stow(weight: 12);
    ax.stow(weight: 9);
    bay.stow(weight: 30);
    bay.stow(weight: 25);
    cod.stow(weight: 5);

    let ax_weight = ax.weight().to_text();
    let bay_weight = bay.weight().to_text();
    let cod_weight = cod.weight().to_text();

    "ax=".concat(other: ax_weight)
        .concat(other: ",bay=")
        .concat(other: bay_weight)
        .concat(other: ",cod=")
        .concat(other: cod_weight)
}

use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < lineup.len() {
        let pony = match lineup.get(i) {
            Some(p) => p,
            None => ??no_element,
        };
        let fed = stable.herd.feed(pony: pony, scoops: 3);
        entries.push(stable.ledger.render(fed));
        i = i + 1;
    }
    io.write(entries.join(","))?;
    return Ok(unit);
}

